int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        out.write(node.buffer, node.start, node.pos - node.start);
        totalSize += node.pos - node.start;
        node = node.next;
    }
    return totalSize;
}

